#nullable enable // autogenerated

using MVZ2.GameContent.Buffs.Contraptions;
using MVZ2.GameContent.Buffs.Projectiles;
using MVZ2.GameContent.Effects;
using MVZ2.Vanilla.Audios;
using MVZ2.Vanilla.Entities;
using MVZ2.Vanilla.Projectiles;
using MVZ2.Vanilla.Properties;
using MVZ2Logic.Entities;
using MVZ2Logic.Level;
using PVZEngine;
using PVZEngine.Buffs;
using PVZEngine.Damages;
using PVZEngine.Entities;
using Tools;
using UnityEngine;
using MVZ2.GameContent.Projectiles;
using PVZEngine.Definitions;

namespace MVZ2.GameContent.Contraptions
{
    /// <summary>
    /// 万象天枢_驱动（驱动发射器 × 万象天枢融合体）。
    /// 普攻：5 个挡位（叠放驱动发射器卡升级），每挡 3 发连发，每满 10 发小箭合并为 1 发大箭（伤害为 10 发小箭之和）。
    /// 触发：过载受伤并短时间（DrivenserTriggerBuff，30 秒）有效挡位 +1，可临时超过满挡变为六档。
    /// 大招：档位叠满，交替发射全部附带诅咒火焰的大箭/小箭，发射完毕后自爆。
    /// </summary>
    [AutoEntityBehaviourDefinition(VanillaContraptionNames.EXPANDispenser_Drivenser)]
    public class EXPANDispenser_Drivenser : EXPANDispenser
    {
        public EXPANDispenser_Drivenser(string nsp, string name) : base(nsp, name)
        {
        }

        public override void Init(Entity entity)
        {
            base.Init(entity);
            // 本融合体不使用导弹盒（覆盖基类的导弹盒初始化）
            SetHasMissileBox(entity, false);
            SetShotIndex(entity, 0);
            SetEvokeShotIndex(entity, 0);
            if (entity.Level.IsIZombie())
            {
                Drivenser.SetUpgradeLevel(entity, I_ZOMBIE_LEVEL);
            }
        }

        protected override void UpdateAI(Entity entity)
        {
            // 大招期间走融合体专属的混合射击逻辑，其余复用基类连发
            if (entity.IsEvoked())
            {
                UpdateEvoke(entity);
            }
            else
            {
                base.UpdateAI(entity);
            }

            // 挡板平滑过渡（参照驱动发射器：视觉缓动逼近有效挡位）
            var blockerBlend = GetBlockerBlend(entity);
            blockerBlend = blockerBlend * 0.5f + GetEffectiveLevel(entity) * 0.5f;
            SetBlockerBlend(entity, blockerBlend);
        }

        protected override void UpdateLogic(Entity entity)
        {
            base.UpdateLogic(entity);
            // 参照基类：挡位满档（或触发超档）时模型进入升级形态，GatlinAlt 随射击左右枪管交替
            entity.SetModelProperty("Upgraded", GetEffectiveLevel(entity) >= MAX_UPGRADE_LEVEL);
            entity.SetModelProperty("GatlinAlt", IsGatlinAlt(entity));
            entity.SetModelProperty("MissileBox", HasMissileBox(entity));
            entity.SetModelProperty("Level", GetEffectiveLevel(entity));
            var blend = GetBlockerBlend(entity);
            entity.SetAnimationFloat("BlockerBlend", blend);
            entity.SetAnimationFloat("RotateSpeed", blend + 1);
        }

        // 普攻连发：总箭数 = 有效挡位 × 3；每满 10 发小箭合并为 1 发大箭（伤害 = 10 发小箭之和）
        // 投射物数 = 大箭数 + 剩余小箭数（1 挡 3 发、2 挡 6 发、3 挡 9 发、4 挡 1大+2小、5 挡 1大+5小）
        public override void OnShootTick(Entity entity)
        {
            int totalArrows = GetEffectiveLevel(entity) * ARROWS_PER_LEVEL;
            int giantCount = totalArrows / GIANT_ARROW_MERGE;
            int normalCount = totalArrows % GIANT_ARROW_MERGE;
            SetGiantShotCount(entity, giantCount);
            SetRepeatCount(entity, giantCount + normalCount);
            SetShotIndex(entity, 0); // 重置连发内发射序号

            var repeatTimer = GetRepeatTimer(entity);
            if (repeatTimer != null)
            {
                int count = GetRepeatCount(entity);
                repeatTimer.ResetTime(Mathf.FloorToInt(15f / count));
                repeatTimer.Frame = 0;
            }
        }

        // 普攻：连发开头射合并大箭（若有），其余为小箭
        public override Entity? Shoot(Entity entity)
        {
            SetGatlinAlt(entity, !IsGatlinAlt(entity));
            int index = GetShotIndex(entity);
            SetShotIndex(entity, index + 1);

            var param = entity.GetShootParams();
            if (index < GetGiantShotCount(entity))
            {
                // 合并大箭：伤害等于 10 发小箭之和
                param.projectileID = VanillaProjectileID.largeArrow;
                param.damage = entity.GetDamage() * GIANT_ARROW_MERGE;
                param.velocity = param.velocity.normalized;
            }
            entity.TriggerAnimation("Shoot");
            return entity.ShootProjectile(param);
        }

        // 触发：过载受伤并短时间有效挡位 +1（复用驱动发射器的过载 buff）
        public override bool CanTrigger(Entity entity)
        {
            // 过载期间不可再次触发
            return base.CanTrigger(entity) && !entity.HasBuff<DrivenserTriggerBuff>();
        }

        protected override void OnTrigger(Entity entity)
        {
            // 不调用基类 OnTrigger（EXPANDispenser 版会装填导弹盒），改做过载触发
            entity.TakeDamage(TRIGGER_HEALTH_COST, new DamageEffectList(), entity);
            entity.AddBuff<DrivenserTriggerBuff>();
            entity.PlaySound(VanillaSoundID.mechanism);
            entity.Level.Spawn(VanillaEffectID.gearParticles, entity.Position, entity);
        }

        // 大招：档位叠满，发射混合箭矢后自爆
        protected override void OnEvoke(Entity entity)
        {
            // 不调用基类 OnEvoke（EXPANDispenser 版会装填导弹盒并挂升级 buff）
            Drivenser.SetUpgradeLevel(entity, MAX_UPGRADE_LEVEL);
            entity.SetEvoked(true);
            SetEvokeShotIndex(entity, 0);
            SetRepeatCount(entity, EVOKE_ARROW_COUNT);
            var repeatTimer = GetRepeatTimer(entity);
            if (repeatTimer != null)
            {
                repeatTimer.ResetTime(REPEAT_INVERVAL);
                repeatTimer.Reset();
            }
            entity.PlaySound(VanillaSoundID.motor);
        }

        // 大招期间逐发射击：大箭/小箭交替，全部附带诅咒火焰，发射完毕自爆
        private void UpdateEvoke(Entity entity)
        {
            var repeatTimer = GetRepeatTimer(entity);
            if (repeatTimer == null)
                return;
            if (repeatTimer.RunToExpired(entity.GetAttackSpeed()))
            {
                ShootEvokeArrow(entity);
                int count = GetRepeatCount(entity) - 1;
                SetRepeatCount(entity, count);
                if (count <= 0)
                {
                    entity.SetEvoked(false);
                    // 自爆（参考驱动发射器过载大招：范围爆炸后自毁）
                    Drivenser.Explode(entity, EVOKE_EXPLOSION_RANGE, EVOKE_EXPLOSION_DAMAGE);
                    entity.Remove();
                    return;
                }
                repeatTimer.Reset();
            }
        }

        private void ShootEvokeArrow(Entity entity)
        {
            int index = GetEvokeShotIndex(entity);
            SetEvokeShotIndex(entity, index + 1);

            entity.TriggerAnimation("Shoot");
            var param = entity.GetShootParams();
            param.soundID = VanillaSoundID.spellCard;
            param.damage = entity.GetDamage() * EVOKE_ARROW_DAMAGE_MULT;

            Entity? projectile;
            if (index % 2 == 0)
            {
                // 诅咒大箭
                param.projectileID = VanillaProjectileID.largeArrow;
                param.velocity = param.velocity.normalized;
                projectile = entity.ShootProjectile(param);
            }
            else
            {
                // 诅咒小箭（跟随普通发射速度）
                param.projectileID = VanillaProjectileID.arrow;
                projectile = entity.ShootProjectile(param);
            }
            // 所有箭矢附带诅咒火焰
            if (projectile != null)
            {
                var fireBuff = projectile.AddBuff<HellfireIgnitedBuff>();
                HellfireIgnitedBuff.Curse(fireBuff);
            }
        }

        // 升级：在其上叠放驱动发射器卡（由 DrivenserPlaceMethod 调用）
        public static bool CanUpgrade(Entity entity)
        {
            return entity.IsEntityOf(VanillaContraptionID.EXPANDispenser_Drivenser)
                && entity.IsFriendlyEntity()
                && Drivenser.GetUpgradeLevel(entity) < MAX_UPGRADE_LEVEL;
        }
        public static void Upgrade(Entity entity)
        {
            if (!CanUpgrade(entity))
                return;
            Drivenser.SetUpgradeLevel(entity, Drivenser.GetUpgradeLevel(entity) + 1);
            entity.PlaySound(VanillaSoundID.mechanism);
            entity.Level.Spawn(VanillaEffectID.gearParticles, entity.Position, entity);
        }

        // 有效挡位：基础挡位 + 过载触发期间的临时加成
        // 触发可短时间超过满挡：满挡 5 时触发临时变为 6 档（15 发 → 18 发 = 1 大箭 + 8 小箭）
        public static int GetEffectiveLevel(Entity entity)
        {
            int level = Drivenser.GetUpgradeLevel(entity);
            if (entity.HasBuff<DrivenserTriggerBuff>())
                level++;
            return Mathf.Min(level, MAX_TRIGGER_LEVEL);
        }

        // 箭矢发射计数（连发内序号，OnShootTick 时重置）
        public static int GetShotIndex(Entity entity) => entity.GetBehaviourField<int>(ID, PROP_SHOT_INDEX);
        public static void SetShotIndex(Entity entity, int value) => entity.SetBehaviourField(ID, PROP_SHOT_INDEX, value);
        // 本次连发中合并大箭的数量（位于连发开头）
        public static int GetGiantShotCount(Entity entity) => entity.GetBehaviourField<int>(ID, PROP_GIANT_SHOT_COUNT);
        public static void SetGiantShotCount(Entity entity, int value) => entity.SetBehaviourField(ID, PROP_GIANT_SHOT_COUNT, value);
        // 大招发射计数（决定箭矢类型循环）
        public static int GetEvokeShotIndex(Entity entity) => entity.GetBehaviourField<int>(ID, PROP_EVOKE_SHOT_INDEX);
        public static void SetEvokeShotIndex(Entity entity, int value) => entity.SetBehaviourField(ID, PROP_EVOKE_SHOT_INDEX, value);
        // 挡板动画混合值（平滑显示挡位）
        public static float GetBlockerBlend(Entity entity) => entity.GetBehaviourField<float>(ID, PROP_BLOCKER_BLEND);
        public static void SetBlockerBlend(Entity entity, float value) => entity.SetBehaviourField(ID, PROP_BLOCKER_BLEND, value);

        private static readonly NamespaceID ID = VanillaContraptionID.EXPANDispenser_Drivenser;
        public static readonly VanillaEntityPropertyMeta<int> PROP_SHOT_INDEX = new VanillaEntityPropertyMeta<int>("ShotIndex");
        public static readonly VanillaEntityPropertyMeta<int> PROP_GIANT_SHOT_COUNT = new VanillaEntityPropertyMeta<int>("GiantShotCount");
        public static readonly VanillaEntityPropertyMeta<int> PROP_EVOKE_SHOT_INDEX = new VanillaEntityPropertyMeta<int>("EvokeShotIndex");
        public static readonly VanillaEntityPropertyMeta<float> PROP_BLOCKER_BLEND = new VanillaEntityPropertyMeta<float>("BlockerBlend");

        public const int MAX_UPGRADE_LEVEL = 5;        // 5 个挡位（初始 0 挡，可叠 5 次驱动发射器）
        public const int MAX_TRIGGER_LEVEL = 6;        // 触发过载期间可临时达到的最大挡位（超过满挡一档）
        public const int ARROWS_PER_LEVEL = 3;         // 每挡 3 发箭
        public const int GIANT_ARROW_MERGE = 10;       // 每 10 发小箭合并为 1 发大箭
        public const int I_ZOMBIE_LEVEL = 2;           // 我是僵尸模式初始挡位
        public const int EVOKE_ARROW_COUNT = 16;       // 大招总箭数（大箭/小箭各半，均带诅咒火焰）
        public const int EVOKE_ARROW_DAMAGE_MULT = 4; // 大招箭伤害倍率
        public const float TRIGGER_HEALTH_COST = 100;   // 触发过载损失血量
        public const float EVOKE_EXPLOSION_RANGE = 60;   // 自爆范围
        public const float EVOKE_EXPLOSION_DAMAGE = 1200; // 自爆伤害
    }
}
